\label{ad-invt}
Let $M$ be a subgroup of $N$. 
\begin{itemize}
\item[(i)] $M$ is {\em $G$-admissible} if the subset
$$ M_*  = \{ g \in G : \alpha_g \in M\} $$
of $G$ is a subgroup of $G$.
\item[(ii)] $M$ is {\em $G$-invariant} if $\theta_g(m) \in M$ for all $g \in G$ and $m \in M$.
\end{itemize}

\label{M-star}
Let $G$ be a transitive subgroup of $\mathrm{Hol}(N)$. For a subgroup $M$ of $N$, the following are equivalent:
\begin{itemize}
\item[(i)] $M$ is $G$-admissible;
\item[(ii)] $g \cdot m \in M$ for all $g \in M_*$ and all $m \in M$;
\item[(iii)] $\theta_g(m) \in M$ for all $g \in M_*$ and all $m \in M$.
\end{itemize}

\label{irred-class}
If $(G,N)$ is any irreducible solution to Question \ref{main-qn} then 
$(G,N)$ is as described in Theorem \ref{irred-constr}. In particular, $N$ is an elementary abelian $2$-group, any non-abelian composition factor of $G$ is isomorphic to the simple group $\mathrm{GL}_3(2)$ of order $168$, and $N$ contains no non-trivial proper $G$-admissible subgroup. Moreover, given $r$ and $H$ as in Theorem \ref{irred-constr}, the corresponding subgroup $G$ of $\mathrm{Hol}(N)$ is unique up to conjugation by $\mathrm{Aut}(N)$.

\label{HGS168}
We interpret Lemma \ref{unique-168} in terms of Hopf-Galois structures. If
$E/K$ is a Galois extension with $\mathrm{Gal}(E/K)=G \cong T$, and $L=E^{G'}$ where $G'$ is a subgroup of $G$ of index $8$, then the existence of a transitive embedding $T \hookrightarrow \mathrm{Aff}(V)=\mathrm{Hol}(V)$ shows that $L/K$ admits at least one Hopf-Galois structure of elementary abelian type $V$. Since there are $8$ transitive subgroups of $\mathrm{Aff}(V)$ isomorphic to $T$, \cite[Proposition 1]{unique} tells us that the number of these Hopf-Galois structures is $8 |\mathrm{Aut}(G,G')|/|\mathrm{Aut}(V)|$, where $\mathrm{Aut}(G,G')$ consists of the automorphisms of $G$ which fix $G'$. Now $|\mathrm{Out}(G)|=2$, the non-trivial element being represented by the automorphism taking each matrix in $\mathrm{GL}_3(2)$ to the transpose of its inverse. Thus $|\mathrm{Aut}(G)|=2 |G|=336$. The automorphisms of $G$ permute the $8$ subgroups of index $8$ transitively, so $|\mathrm{Aut}(G,G')|= |\mathrm{Aut}(G)|/8=42$. Since $\mathrm{Aut}(V)\cong G$, we find that $L/K$ admits $2$ Hopf-Galois structures of type $V$.

\label{comp-factors}
Let $(G,V)$ satisfy Hypothesis \ref{p-sol-stab}, and let 
\begin{equation}  \label{comp-series}
   \{1\} =G_0 \triangleleft G_1 \triangleleft \cdots \triangleleft  G_m=G 
\end{equation}
be any composition series for $G$. Then the following hold for $1 \leq i \leq m$:
\begin{itemize}
\item[(i)] the pair $(G_i,V)$ also satisfies Hypothesis \ref{p-sol-stab};
\item[(ii)] the simple group $G_i/G_{i-1}$ has a soluble subgroup of index $p^s$ for some $s \geq 0$.
\end{itemize}

\label{irred-soc}
Let $G$ be an insoluble subgroup of $\mathrm{Aff}(V)$ satisfying Hypothesis \ref{p-sol-stab}, and suppose that $(G,V)$ is irreducible. Let $S=\mathrm{soc}(G)$.
Then $S$ is a direct product of non-abelian simple groups:
\begin{equation} \label{soc-G} 
  S = T_1 \times \cdots \times T_r. 
\end{equation}  
Conjugation by $G$ permutes $\{T_1, \ldots, T_r\}$, and each minimal normal subgroup of $G$ is the direct product of all the $T_i$ lying in a single orbit.

\label{mk-ry-prop}
For each minimal normal subgroup $J$ of $G$, we have 
\begin{equation} \label{mk-ry}
     m y(J) = r(J) z(J).
\end{equation}
Moreover, $y(J) \geq 1$ and $z(J) \geq 1$.

\label{key-ineq-lemma}
With the above notation,
\begin{equation} \label{key-ineq}
  m \prod_J d_p(T_J)^{y(J)} < 
        \sum_J r(J) \left( v_p(|\mathrm{Aut}(T_J)|)  + \frac{1}{p-1}\right), 
\end{equation}
the product and sum being over all minimal normal subgroups $J$ of $G$.

\label{no-CFSG}
Let $(G,V)$ be an irreducible solution to Question \ref{main-qn}: $V$ is a finite soluble 
group, $G$ is an insoluble 
transitive subgroup of $\mathrm{Hol}(V)$ such that $V$ has no non-trivial proper $G$-invariant normal subgroup, and the stabiliser in $G$ of any element of $V$ is soluble. Then
\begin{itemize}
\item[(i)] $V$ is an elementary abelian group: $V \cong \mathbb{F}_p^n$ for some prime $p$ and some $n \geq 1$, and,
viewed as a subgroup of $\mathrm{Aff}(V)$, the group $G$ contains no non-trivial translations;
\item[(ii)] $\mathrm{soc}(G)$ is the direct product of all the minimal normal subgroups $J$ of $G$,  
each of which is in turn a direct product $J \cong T_J^{r(J)}$ for some non-abelian simple group $T_J$ and some $r(J) \geq 1$;
\item[(iii)] $G$ embeds in $\mathrm{Aut}(\mathrm{soc}(G))$;
\item[(iv)] each of the non-abelian simple groups $T_J$ has a soluble subgroup of $p$-power index;
\item[(v)] there is an integer $m$, and integers $y(J)$, $z(J)$ for each $J$, such that $1 \leq y(J) \leq r(J)$, $1 \leq z(J) \leq m$, and 
(\ref{mk-ry}) and (\ref{key-ineq}) hold.
\end{itemize}

(i) follows from Lemma \ref{irred-el-ab}, Proposition \ref{trans} and Lemma \ref{p-normal}; 
(ii) from Lemma \ref{irred-soc}; (iii) from Corollary \ref{centraliser}; (iv) from 
Lemma \ref{comp-factors}(ii); and (v) recapitulates Proposition \ref{mk-ry-prop} and Lemma \ref{key-ineq-lemma}.

\label{Guralnick}
If $T$ is a non-abelian finite simple group with a proper subgroup $R$ of
prime-power index $p^a$, then one of the following holds. 
\begin{itemize} 
\item[(i)] $T=A_n$ and $R=A_{n-1}$ with $n=p^a$;
\item[(ii)] $T=\mathrm{PSL}_n(q)$, $p^a=(q^n-1)/(q-1)$ and $R$ is the
  stabiliser of a line or a hyperplane in $\mathbb{F}_q^n$; 
\item[(iii)] $T=\mathrm{PSL}_2(11)$ and $R=A_5$ of index $11$;
\item[(iv)] $T=M_{23}$, $R=M_{22}$ or $T=M_{11}$, $R=M_{10}$;
\item[(v)] $T=\mathrm{PSU}_4(2) \cong \mathrm{PSp}_4(3)$ and $R$ has index $27$.
\end{itemize}

\label{simple-sol-p}
If $T$ is a non-abelian finite simple group with a soluble subgroup
of prime-power index $p^a$, then the triple $(T,p,a)$ is one of the following: 
\begin{itemize}
	\item[(i)] $(\mathrm{PSL}_3(2),7,1)$; 
\item[(ii)] $(\mathrm{PSL}_3(3), 13, 1)$;
\item[(iii)] $(\mathrm{PSL}_2(2^s), p,1)$ where $p=2^s+1$ is a Fermat prime with $p \geq 5$;
\item[(iv)] $(\mathrm{PSL}_2(8),3,2)$;
\item[(v)] $(\mathrm{PSL}_2(q),2,a)$ where $q=2^a-1$ is a Mersenne prime with $q \geq 7$. 
\end{itemize}

\label{just-168}
Let $(G,V)$ be an irreducible solution to Question \ref{main-qn}. Then, in the notation of Theorem \ref{no-CFSG}, $p=2$ and for each minimal normal subgroup $J$ of $G$, the simple group 
$T_J$ is the group $T=\mathrm{PSL}_2(7) \cong \mathrm{GL}_3(2)$ of order $168$. Moreover, one of the following holds:
\begin{itemize}
\item[(i)] $G$ contains exactly two minimal normal subgroups $J_1\cong J_2 \cong T^r$ with $r=m$, $y(J_1)=y(J_2)=z(J_1)=z(J_2)=1$;
\item[(ii)] $G$ contains a unique minimal normal subgroup $J=\mathrm{soc}(G) \cong T^r$ with $r=2m$, $y(J)=2$, $z(J)=1$;
\item[(iii)] $G$ contains a unique minimal normal subgroup $J=\mathrm{soc}(G) \cong T^r$ with $r=m$, $y(J)=z(J)=1$.
\end{itemize}

\label{J-norm}
With the above notation, 
$$  \{X \in \mathrm{Aff}(V) : X \cdot 0_V =0_V \mbox{ and } XJX^{-1} = J\}= J' \rtimes S_r.  $$
